var cursor = new DataTable("Cursor");
cursor.Columns.Add("More", typeof(Boolean)); cursor.Columns.Add("After", typeof(String));
cursor.Rows.Add(more, after); oDS.Tables.Add(table); oDS.Tables.Add(cursor);
